android.code:
// App pseudocode: choose the activated user, not an arbitrary first account.
val user = requireSelectedLocalUser()
loginWithSelectedClient(clientId, user) { result ->
    when (result) {
        is Challenge -> renderRequestedFields(result)
        is Completed -> verifyAuthenticatedSdkState(user)
        is Failed -> showLoginFailure(result) // no implicit reactivation
    }
}

ios.code:
// App pseudocode; the SDK wrapper exposes version-dependent overloads.
let user = try requireSelectedLocalUser()
loginWithSelectedClient(clientId, user: user) { result in
    switch result {
    case .challenge(let fields): renderRequestedFields(fields)
    case .completed: verifyAuthenticatedSDKState(user)
    case .failed(let error): showLoginFailure(error)
    }
}
